using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class BridgeMemberAudit{static BridgeMemberAudit(){EditorApplication.update+=Run;}static void Run(){if(EditorApplication.isCompiling||!File.Exists("BridgeMemberAudit.request"))return;File.Delete("BridgeMemberAudit.request");try{var f=SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).First(f=>f.name=="bridge");var data=typeof(FinalPathwayRepair).GetMethod("Read",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static).Invoke(null,new object[]{f.sharedMesh});var ty=data.GetType();var v=(Vector3[])ty.GetField("p").GetValue(data);var ix=(int[])ty.GetField("ids").GetValue(data);var parent=Enumerable.Range(0,v.Length).ToArray();Func<int,int> find=null;find=i=>parent[i]==i?i:(parent[i]=find(parent[i]));Action<int,int> join=(a,b)=>parent[find(a)]=find(b);var pos=new Dictionary<Vector3,int>();for(int i=0;i<v.Length;i++){var p=new Vector3(Mathf.Round(v[i].x*100),Mathf.Round(v[i].y*100),Mathf.Round(v[i].z*100));if(pos.ContainsKey(p))join(i,pos[p]);else pos[p]=i;}for(int k=0;k<ix.Length;k+=3){join(ix[k],ix[k+1]);join(ix[k],ix[k+2]);}var log=new System.Text.StringBuilder();log.AppendLine("Transform="+f.transform.position+" rotation="+f.transform.eulerAngles+" scale="+f.transform.lossyScale);foreach(var g in Enumerable.Range(0,v.Length).GroupBy(find).OrderByDescending(g=>g.Count())){var b=new Bounds(f.transform.TransformPoint(v[g.First()]),Vector3.zero);foreach(int i in g)b.Encapsulate(f.transform.TransformPoint(v[i]));log.AppendLine(g.Count()+" "+b);}var view=SceneView.lastActiveSceneView;if(view&&view.camera)log.AppendLine("CAM="+view.camera.transform.position+" direction="+view.camera.transform.forward);File.WriteAllText("FinalEnvironmentRoadReview/BridgeMembers.txt",log.ToString());}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/BridgeMembers.txt",e.ToString());}}}
